import{isoUtc}from"./extract.min.js";import{distanceToCenterLy}from"./report.min.js";import{MAIN_STORY_MISSION_IDS,EXPEDITION_LORE_MISSION_IDS}from"./seed.min.js";export function parseTs(ts){const s=ts.slice(0,19);const y=+s.slice(0,4);const mo=+s.slice(5,7);const d=+s.slice(8,10);const h=s.length>10?+s.slice(11,13):0;const mi=s.length>10?+s.slice(14,16):0;const se=s.length>10?+s.slice(17,19):0;return Date.UTC(y,mo-1,d,h,mi,se)}function daysBetween(msA,msB){return Math.floor((msA-msB)/864e5)}export function relDuration(days){if(days<1)return"that same day";if(days<4)return"days later";if(days<20)return"weeks later";if(days<75)return"months later";if(days<200)return"many months later";if(days<420)return"nearly a year later";if(days<800)return"over a year later";return"years later"}function flyDistanceClass(meters){const m=meters??0;if(m<=0)return 0;if(m<1e6)return 1;if(m<1e7)return 2;if(m<3e7)return 3;return 4}function walkDistanceClass(meters){const m=meters??0;if(m<=0)return 0;if(m<5e4)return 1;if(m<3e5)return 2;if(m<1e6)return 3;return 4}export function season(ms){const m=new Date(ms).getUTCMonth()+1;const idx={12:0,1:0,2:0,3:1,4:2,5:2,6:3,7:3,8:4,9:5,10:5,11:6}[m];return["deep winter","early spring","spring","summer","late summer","autumn","late autumn"][idx]}const CORE_EDGE_LY=3500;function findIntergalacticJump(report){const track=report.protagonist_track||[];for(let i=1;i<track.length;i++){const from=track[i-1];const to=track[i];if(to.galaxy===from.galaxy){continue}if(from.distance_to_center_ly>CORE_EDGE_LY){continue}return{from_galaxy:from.galaxy,to_galaxy:to.galaxy,ts:to.ts,from_system:from.sysaddress,from_distance_ly:from.distance_to_center_ly}}return null}const NON_HOME_BASE_TYPES=new Set(["FreighterBase","PlayerShipBase"]);function findFavoriteBase(trajectory){if(!trajectory||!trajectory.bases.length){return null}const homes=trajectory.bases.filter(b=>!NON_HOME_BASE_TYPES.has(b.base_type));if(!homes.length){return null}const sorted=homes.sort((a,b)=>{const ta=a.last_update??0;const tb=b.last_update??0;return tb-ta});const fav=sorted[0];return{name:fav.name,base_type:fav.base_type,sysaddress:fav.sysaddress,galaxy:fav.galaxy,region:{hex:fav.sysaddress.slice(3),galaxy:fav.galaxy},last_update_ms:fav.last_update}}export function buildBeats(rep){const t0=rep.own_span?.first?parseTs(rep.own_span.first):rep.first_protagonist_record?parseTs(rep.first_protagonist_record.ts):parseTs(rep.period.first);const beats=[];const rel=ms2=>relDuration(daysBetween(ms2,t0));const stats=rep.milestones?.stats??{};const birthSys=rep.birth.sysaddress;const startYear=rep.own_span?.first?new Date(parseTs(rep.own_span.first)).getUTCFullYear():null;beats.push({type:"first_system",ts:null,when_rel:"at the very start",theme:"birth",salience:.95,facts:{sysaddress:birthSys,planet_index:rep.birth.planet_index,start_year:startYear}});const community=rep.cradle?.other_users??[];if(community.length>=3){beats.push({type:"community_phase",ts:null,when_rel:"in the first weeks",theme:"shared unknown",salience:.7,facts:{distinct_users:community.length}})}const fa=rep.first_named_record;if(fa){const adt=parseTs(fa.ts);beats.push({type:"first_naming",ts:fa.ts,when_rel:rel(adt),season:season(adt),theme:"first trace",salience:.9,facts:{sysaddress:fa.sysaddress,system_name:fa.system_name,planet_name:fa.planet_name}})}const journeyStart=rep.birth.source==="save_field"?rep.birth.sysaddress:rep.first_record.sysaddress;const cj=rep.center_journey;const birthDist=distanceToCenterLy(journeyStart);const actualProgress=birthDist-cj.closest_reached_ly;beats.push({type:"center_journey",ts:cj.closest_date,when_rel:"over the months",theme:actualProgress>100?"the center as horizon":"orbiting the cradle",salience:.85,facts:{closest_system:cj.closest_system,blackhole_warps:stats.blackhole_warps??0}});const igj=findIntergalacticJump(rep);if(igj){beats.push({type:"intergalactic_jump",ts:igj.ts,when_rel:rel(parseTs(igj.ts)),season:season(parseTs(igj.ts)),theme:"beyond the horizon",salience:.9,facts:{to_galaxy:igj.to_galaxy}})}const ownLastIso=rep.own_span?.last??rep.period.last;const favBase=findFavoriteBase(rep.trajectory);if(favBase){const lastUpdateTs=favBase.last_update_ms?isoUtc(favBase.last_update_ms):ownLastIso;const lastUpdateMs=favBase.last_update_ms??parseTs(ownLastIso);beats.push({type:"favorite_base",ts:lastUpdateTs,when_rel:rel(lastUpdateMs),theme:"home",salience:.75,facts:{sysaddress:favBase.sysaddress,name:favBase.name,bases_built:rep.trajectory?.bases?.length??0}})}const big=rep.biggest_sessions[0];const ownLastDate=(rep.own_span?.last??rep.period.last).slice(0,10);if(big.date===ownLastDate){beats.push({type:"final_session",ts:rep.own_span?.last??rep.period.last,when_rel:"on the very last day",season:season(parseTs(rep.own_span?.last??rep.period.last)),theme:"traces left behind",salience:1,facts:{events_that_day:big.events}})}const journeyEndsTs=rep.own_span?.last??rep.period.last;beats.push({type:"journey_ends",ts:journeyEndsTs,when_rel:"at the very end",season:season(parseTs(journeyEndsTs)),theme:"the last place",salience:1,facts:{total_systems:rep.totals.systems,total_regions:rep.totals.regions,total_galaxies:rep.totals.galaxies.length,total_events:rep.totals.events,active_days:rep.totals.active_days,total_deaths:rep.milestones?.total_deaths??0,systems_discovered:stats.systems_discovered??0,planets_discovered:stats.planets_discovered??0,dist_fly_class:flyDistanceClass(stats.dist_fly),dist_walked_class:walkDistanceClass(stats.dist_walked),sentinel_kills:stats.sentinel_kills??0}});const ms=rep.milestones;if(ms){const firstTs=rep.system_first_ts??{};const dateOf=(galaxy,sysaddress)=>firstTs[galaxy+"|"+sysaddress]??null;const hasFleetCount=(stats.frigates??0)>0||(rep.ships_owned??0)>0||(stats.ships_bought??0)>0;if(ms.freighter&&ms.freighter.name||hasFleetCount){beats.push({type:"freighter_named",ts:null,when_rel:"somewhere along the way",theme:"the mothership",salience:.55,facts:{name:ms.freighter?.name??null,frigates:stats.frigates??0,ships_owned:rep.ships_owned??0,ships_bought:stats.ships_bought??0}})}const atlasTs=rep.first_atlas?rep.first_atlas.ts:null;if(atlasTs){beats.push({type:"atlas_encounter",ts:atlasTs,when_rel:rel(parseTs(atlasTs)),theme:"the Atlas",salience:.7,facts:{sysaddress:rep.first_atlas.sysaddress,galaxy:rep.first_atlas.galaxy,system_name:rep.first_atlas.system_name||""}})}if(ms.purple&&ms.purple.discovered){const purpleTs=ms.purple.first?dateOf(ms.purple.first.galaxy,ms.purple.first.sysaddress):null;beats.push({type:"purple_systems",ts:purpleTs,when_rel:purpleTs?rel(parseTs(purpleTs)):"somewhere along the way",theme:"purple stars",salience:.65,facts:{first_system:ms.purple.first?{sysaddress:ms.purple.first.sysaddress,galaxy:ms.purple.first.galaxy}:null}})}const owned=(Array.isArray(ms.settlements)?ms.settlements:[]).filter(s=>s.owner&&s.owner===rep.protagonist);if(owned.length>0){const claimBySeed=new Map((ms.settlementHistory??[]).filter(h=>h.claimed_ts).map(h=>[h.seed_value,h.claimed_ts]));const claimTsFor=s=>claimBySeed.get(s.seed_value)??s.first_activity??null;const acts=owned.map(claimTsFor).filter(t=>t);const settleTs=acts.length?isoUtc(Math.min(...acts)):null;const first=owned.reduce((best,s)=>{const t=claimTsFor(s);if(!best)return{s,t};return t&&(!best.t||t<best.t)?{s,t}:best},null);beats.push({type:"settlements",ts:settleTs,when_rel:settleTs?rel(parseTs(settleTs)):"somewhere along the way",theme:"the overseer",salience:.4,facts:{names:owned.map(s=>s.name).filter(Boolean),total_population:owned.reduce((n,s)=>n+(s.population??0),0),sysaddress:first?.s?.sysaddress??null}})}const pets=(ms.pets??[]).filter(p=>p.birth_ts>0);if(pets.length>0){const firstPet=pets.reduce((a,b)=>b.birth_ts<a.birth_ts?b:a);const petTs=isoUtc(firstPet.birth_ts);beats.push({type:"first_pet",ts:petTs,when_rel:rel(parseTs(petTs)),season:season(parseTs(petTs)),theme:"first companion",salience:.5,facts:{sysaddress:firstPet.sysaddress,creature_id:firstPet.creature_id,name:firstPet.name,pets_owned:stats.pets_owned??0,creatures_fed:stats.creatures_fed??0,creatures_discovered:stats.creatures_discovered??0}})}if(ms.multitool&&ms.multitool.name){beats.push({type:"multitool_named",ts:null,when_rel:"somewhere along the way",theme:"the tool you carry",salience:.35,facts:{name:ms.multitool.name,is_large:!!ms.multitool.is_large}})}const progress=ms.missionProgress??{};const doneAgainst=table=>table.filter(id=>(progress[id]??0)>0);const mainDone=doneAgainst(MAIN_STORY_MISSION_IDS);if(mainDone.length>0){beats.push({type:"main_story_arc",ts:null,when_rel:"across the story",theme:"the main thread",salience:.6,facts:{done_ids:mainDone}})}const loreDone=doneAgainst(EXPEDITION_LORE_MISSION_IDS);if(loreDone.length>0){beats.push({type:"expedition_lore",ts:null,when_rel:"along the way",theme:"side stories",salience:.35,facts:{done_ids:loreDone,pirates_killed:stats.pirates_killed??0,flora_discovered:stats.flora_discovered??0}})}}if(rep.play_time_seconds){beats.push({type:"total_playtime",ts:null,when_rel:"across the whole journey",theme:"time lived",salience:.5,facts:{seconds:rep.play_time_seconds}})}beats.sort((a,b)=>{if(a.ts===null&&b.ts===null)return 0;if(a.ts===null)return-1;if(b.ts===null)return 1;return a.ts<b.ts?-1:a.ts>b.ts?1:0});return beats}export function anonymizeBeats(beats,protagonist){return beats.map(b=>{const facts={...b.facts};if("user"in facts){if(protagonist!==null&&facts.user===protagonist){facts.user="you"}else{delete facts.user}}delete facts.sample_users;return{...b,facts}})}export function buildStoryGraph(rep){return{beats:anonymizeBeats(buildBeats(rep),rep.protagonist)}}
